<?php require '../config/db.php';require '../includes/functions.php';$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(strlen($name)<2)json_response(false,'Enter your full name.',[],422);if(!filter_var($email,FILTER_VALIDATE_EMAIL))json_response(false,'Enter a valid email address.',[],422);if(strlen($pass)<8)json_response(false,'Password must contain at least 8 characters.',[],422);$c=$pdo->prepare('SELECT id FROM users WHERE email=?');$c->execute([$email]);if($c->fetch())json_response(false,'That email is already registered.',[],409);$role=((int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn()===0)?'admin':'editor';$pdo->prepare('INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,?,\'active\')')->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role]);json_response(true,'Account created. You can now log in.');